import * as THREE from 'three';

/** Thickness of the seat slab (meters). */
export const SEAT_THICKNESS = 0.05;

/** Thickness of the backrest panel (meters). */
export const BACK_THICKNESS = 0.04;

/**
 * Build a parametric chair as a THREE.Group.
 *
 * Coordinate conventions:
 * - The chair sits on the y=0 plane, centered on the origin.
 * - Seat spans x in [-seatWidth/2, seatWidth/2] and z in [-seatDepth/2, seatDepth/2].
 * - The rear edge of the seat is at z = -seatDepth/2; the backrest leans
 *   backward (further into -z) as backAngleDeg increases.
 *
 * Named children: four meshes named "leg", one "seat", one "backrest".
 *
 * @param {object} opts
 * @param {number} opts.seatWidth      Total width of the seat along x.
 * @param {number} opts.seatDepth      Depth of the seat along z.
 * @param {number} opts.seatHeight     Height of the seat top surface from the floor.
 * @param {number} opts.backHeight     Height of the backrest panel above the seat.
 * @param {number} opts.backAngleDeg   Backrest tilt about the x axis, in degrees.
 * @param {number} opts.legThickness   Square cross-section side of each leg.
 * @returns {THREE.Group}
 */
export function buildChair({
  seatWidth,
  seatDepth,
  seatHeight,
  backHeight,
  backAngleDeg = 0,
  legThickness,
}) {
  const group = new THREE.Group();

  const wood = new THREE.MeshStandardMaterial({ color: 0x8b5a2b, roughness: 0.7 });

  // --- Legs: square-section boxes, tops flush with the seat underside ---
  const legLength = seatHeight - SEAT_THICKNESS;
  const insetX = seatWidth / 2 - legThickness / 2;
  const insetZ = seatDepth / 2 - legThickness / 2;

  for (const [x, z] of [
    [insetX, insetZ],
    [-insetX, insetZ],
    [insetX, -insetZ],
    [-insetX, -insetZ],
  ]) {
    const leg = new THREE.Mesh(
      new THREE.BoxGeometry(legThickness, legLength, legThickness),
      wood
    );
    leg.position.set(x, legLength / 2, z);
    leg.name = 'leg';
    group.add(leg);
  }

  // --- Seat slab: top surface at y = seatHeight ---
  const seat = new THREE.Mesh(
    new THREE.BoxGeometry(seatWidth, SEAT_THICKNESS, seatDepth),
    wood
  );
  seat.position.set(0, seatHeight - SEAT_THICKNESS / 2, 0);
  seat.name = 'seat';
  group.add(seat);

  // --- Backrest: panel hinged at the seat's rear top edge ---
  // Pivot sits exactly on the rear edge (z = -seatDepth/2, y = seatHeight).
  const pivot = new THREE.Group();
  pivot.position.set(0, seatHeight, -seatDepth / 2);
  // Negative rotation so the top of the panel swings backward (-z).
  pivot.rotation.x = -THREE.MathUtils.degToRad(backAngleDeg);

  const backrest = new THREE.Mesh(
    new THREE.BoxGeometry(seatWidth, backHeight, BACK_THICKNESS),
    wood
  );
  // Offset so the panel's front face is flush with the pivot plane:
  // at 0 degrees the front face lies exactly at the seat's rear z.
  backrest.position.set(0, backHeight / 2, BACK_THICKNESS / 2);
  backrest.name = 'backrest';
  pivot.add(backrest);
  group.add(pivot);

  return group;
}

/**
 * World-space axis-aligned bounding box of a chair.
 *
 * @param {THREE.Object3D} chair
 * @returns {THREE.Box3}
 */
export function chairBounds(chair) {
  return new THREE.Box3().setFromObject(chair);
}

