import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildChair, chairBounds, SEAT_THICKNESS } from '../src/chair.js';

const BASE = {
  seatWidth: 1.0,
  seatDepth: 0.9,
  seatHeight: 0.9,
  backHeight: 0.8,
  backAngleDeg: 0,
  legThickness: 0.06,
};

function legsOf(chair) {
  return chair.children.filter((c) => c.isMesh && c.name === 'leg');
}

describe('buildChair', () => {
  it('has exactly four leg meshes whose tops meet the seat underside', () => {
    const chair = buildChair(BASE);
    const legs = legsOf(chair);
    expect(legs).toHaveLength(4);

    for (const leg of legs) {
      const box = new THREE.Box3().setFromObject(leg);
      expect(box.max.y).toBeCloseTo(BASE.seatHeight - SEAT_THICKNESS, 6);
    }
  });

  it('widens its bounds by exactly the increase in seatWidth', () => {
    const narrow = chairBounds(buildChair({ ...BASE, seatWidth: BASE.seatWidth }));
    const wide = chairBounds(buildChair({ ...BASE, seatWidth: BASE.seatWidth + 0.2 }));

    const widthNarrow = narrow.max.x - narrow.min.x;
    const widthWide = wide.max.x - wide.min.x;

    expect(widthWide - widthNarrow).toBeCloseTo(0.2, 6);
  });

  it('keeps the backrest top edge at the seat rear z when angle is 0', () => {
    const chair = buildChair({ ...BASE, backAngleDeg: 0 });
    chair.updateMatrixWorld(true);

    const back = chair.getObjectByName('backrest');
    // Top-front-center vertex of the backrest panel, in mesh-local space.
    const v = new THREE.Vector3(0, BASE.backHeight / 2, -back.geometry.parameters.depth / 2);
    back.localToWorld(v);

    const seatRearZ = -BASE.seatDepth / 2;
    expect(v.z).toBeCloseTo(seatRearZ, 6);
  });

  it('moves the backrest top edge backward with a 15 degree tilt', () => {
    const buildTopZ = (angle) => {
      const chair = buildChair({ ...BASE, backAngleDeg: angle });
      chair.updateMatrixWorld(true);
      const back = chair.getObjectByName('backrest');
      const v = new THREE.Vector3(0, BASE.backHeight / 2, -back.geometry.parameters.depth / 2);
      back.localToWorld(v);
      return v.z;
    };

    const zUpright = buildTopZ(0);
    const zTilted = buildTopZ(15);

    const seatRearZ = -BASE.seatDepth / 2;
    expect(zTilted).toBeLessThan(zUpright);
    expect(zTilted).toBeLessThan(seatRearZ); // backward = further into -z
  });

  it('chairBounds returns a valid Box3 enclosing the whole chair', () => {
    const chair = buildChair(BASE);
    const box = chairBounds(chair);
    expect(box).toBeInstanceOf(THREE.Box3);
    expect(box.isEmpty()).toBe(false);
    expect(box.min.y).toBeCloseTo(0, 6); // legs reach the floor
    expect(box.max.y).toBeGreaterThan(BASE.seatHeight + BASE.backHeight * 0.9);
  });
});

